//! The engine C ABI, generated by bindgen from the header: change the header, not
//! this file. Enums arrive as integer constants, so a value an engine adds later is
//! refused rather than undefined behavior; records carry generated layout assertions.

// Generated code follows C's naming and carries the whole surface, including what this host has
// no call for yet
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
